// CSD_RATIONALE_BEGIN
// Context-aware EOS-break span strategy for symbolic math.
//
// Root causes:
// 1. Premature close: AdaptiveConstrainedStep returns EOS after the parser first
//    accepts a short prefix (e.g. single variable `total`). The span closes there
//    and the rest of the formula lands in free text as unspanned arithmetic.
// 2. Multiple tiny spans: when the model writes `<<total>> - <<2>> * <<n>> - <<m>>`,
//    each operand is constrained separately; the evaluator picks the last tiny span.
//
// Fix A — context-aware minimum span length: detect "final answer" spans by
// checking whether "The final answer is" appears in the generated prefix before
// the current span. For final-answer spans, require >= 12 constrained tokens
// before attempting CloseConstrainedSpan. For intermediate reasoning spans the
// gate is 1 (allow immediate close). The 12-token floor forces the span to span
// multi-operator formulas rather than single-variable stubs.
//
// Fix B — EOS-break + post-loop close: when the model chooses EOS inside the
// force-continuation window, we break the loop with the span still open but
// complete. A post-loop block calls CloseConstrainedSpan on the now-complete
// prefix. This correctly captures `total - 2*n - m` (EOS fires at 7 tokens,
// post-loop closes) and `(n1*d1+n2*d2) // 12` (EOS fires at 11 tokens after
// being forced past the 9-token premature close point).
//
// Guidance is positive ("write the complete formula") rather than prohibitive,
// avoiding the "no_span_emitted" failures seen in attempt 3.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// parser_validity: `insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)`
//
//   Unconstrained branch: while !insideConstrainedOut the implication is vacuous.
//   When RenderedEndsWith(generated,"<<") fires we set currentConstrainedOut := []
//   and parser.IsValidPrefix([]) holds by method precondition.
//
//   Complete + close branch (|currentConstrainedOut| >= minTokensNeeded):
//   CloseConstrainedSpan sets insideConstrainedOut := false, making the
//   implication vacuously true, and clears currentConstrainedOut to [].
//
//   Force-continuation branch (complete but fewer than minTokensNeeded tokens)
//   and not-complete branch: AdaptiveConstrainedStep returns EOS (we break;
//   insideConstrainedOut remains true but the span is still valid so the
//   invariant holds on loop exit) or a token t such that
//   parser.IsValidPrefix(currentConstrainedOut + [t]). AppendConstrainedToken
//   appends exactly t, preserving IsValidPrefix.
//
//   Post-loop close: gated by parser.IsCompletePrefix(currentConstrainedOut), so
//   CloseConstrainedSpan's precondition is satisfied; it sets insideConstrainedOut
//   := false.
//
// progress: `|generated| <= |generatedPrefix| + steps`
//
//   Unconstrained branch: steps += 1; generated grows by at most 1 token (EOS
//   never appended; "<<" is exactly 1 visible token via RenderedEndsWith).
//
//   Close branch: steps += 1; CloseConstrainedSpan appends at most 1 ">>" token.
//   Visible growth = 1 = steps growth.
//
//   Force-continuation and not-complete branches: steps += 1; AdaptiveConstrainedStep
//   costs 1 step; AppendConstrainedToken appends at most 1 visible token. Visible
//   growth <= 1 = steps growth.
//
//   Post-loop close: guarded by `steps < maxSteps`, so steps + 1 <= maxSteps;
//   CloseConstrainedSpan appends 1 visible ">>" and steps is incremented by 1.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance := "Solve step by step in plain text. At the very end write: The final answer is <<FORMULA>> where FORMULA is a COMPLETE arithmetic expression using ALL relevant symbolic variables and operators. Include the entire expression inside the << >>. For example: The final answer is <<n1 * d + n2 * d2 // 12>>.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var finalSpanMinTokens: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    // Detect whether this is the final-answer span
    var preSpanTokens := generated[..|generated| - |currentConstrainedOut|];
    var preSpanText := CSDHelpers.PrefixToString(preSpanTokens);
    var isFinalSpan := CSDHelpers.CountSubstring(preSpanText, "The final answer is") >= 1;
    var minTokensNeeded: nat := if isFinalSpan then finalSpanMinTokens else 1;

    if |currentConstrainedOut| >= minTokensNeeded {
      // Span is complete and long enough — close it
      var cg, ci, cc := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else {
      // Force continuation to grow the formula past short complete prefixes
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, 12, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        // Model signals "done" — break and let post-loop close the complete span
        break;
      }
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  } else {
    // Span not yet complete — generate the next parser-valid token
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.AdaptiveConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, 12, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    var ag, ai, ac := helpers.AppendConstrainedToken(
      lm, parser, generated, currentConstrainedOut, next
    );
    generated := ag;
    insideConstrainedOut := ai;
    currentConstrainedOut := ac;
  }
}

// Post-loop cleanup: if we broke out of the loop while inside a complete span,
// close it now (covers EOS-break after completing the full formula).
if insideConstrainedOut && parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
  var cg, ci, cc := helpers.CloseConstrainedSpan(
    lm, parser, generated, currentConstrainedOut
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + 1;
}

cost := steps;

